function citizenHeading(p){const t=p.path?.length?p.path[0]:p.target;return t?Math.atan2(t[0]-p.x,t[1]-p.z):0;}
function cameraObstacles(){
 return city.map(([x,z,k])=>({x,z,rx:(2.4+k*.42)/2+.25,rz:(2.1+k*.18)/2+.25,h:3.65}))
  .concat([{x:0,z:-1,rx:3.6,rz:2.8,h:6.4},{x:0,z:5,rx:1.7,rz:1.1,h:2.35},
   {x:CRAFT_DISTRICT.x,z:CRAFT_DISTRICT.z,rx:4.3,rz:3.5,h:7.5},
   {x:SCENIC_SITES.sanctuary.x,z:SCENIC_SITES.sanctuary.z,rx:4,rz:5.5,h:12}]);
}
function portraitRayBlocked(p,angle,distance,tilt){
 const targetY=terrain(p.x,p.z)+.98,rad=Math.cos(tilt)*distance,obstacles=cameraObstacles();
 for(let n=1;n<=22;n++){
  const t=n/22,x=p.x+Math.sin(angle)*rad*t,z=p.z+Math.cos(angle)*rad*t,y=targetY+Math.sin(tilt)*distance*t;
  for(const b of obstacles)if(Math.abs(x-b.x)<b.rx&&Math.abs(z-b.z)<b.rz&&y<terrain(b.x,b.z)+b.h+.12)return true;
  for(const tree of trees)if(Math.hypot(x-tree.x,z-tree.z)<tree.s*.95&&y<terrain(tree.x,tree.z)+tree.s*4.4&&y>terrain(tree.x,tree.z)+.4)return true;
 }
 return false;
}
function chooseCitizenView(p){
 const heading=citizenHeading(p),offsets=[.35,-.35,.8,-.8,1.25,-1.25,1.8,-1.8,2.5,-2.5,Math.PI,0];
 for(const distance of [4.8,3.6])for(const tilt of [.23,.42,.65])for(const offset of offsets){const angle=heading+offset;if(!portraitRayBlocked(p,angle,distance,tilt))return {angle,distance,tilt};}
 return {angle:heading+.35,distance:4.8,tilt:.85};
}
function inspectCitizen(index=selectedCitizen){
 if(!Number.isInteger(index)||index<0||index>=people.length)throw Error('Unknown citizen index');
 selectedCitizen=index;const p=people[index],view=chooseCitizenView(p);
 citizenInspectionActive=true;document.body.dataset.portrait='true';follow=true;cinematic=false;focusPoint=[p.x,p.z];yaw=view.angle;zoom=view.distance;pitch=view.tilt;
 document.getElementById('focus').classList.add('active');document.getElementById('camera').classList.remove('active');
 updateUI();return citizenInspection();
}
function citizenInspection(){
 const p=people[selectedCitizen],targetY=terrain(p.x,p.z)+.98,rad=Math.cos(pitch)*zoom;
 return {active:citizenInspectionActive,index:selectedCitizen,name:p.name,distance:zoom,
  eye:[focusPoint[0]+Math.sin(yaw)*rad,targetY+Math.sin(pitch)*zoom,focusPoint[1]+Math.cos(yaw)*rad],
  blocked:citizenInspectionActive?portraitRayBlocked(p,yaw,zoom,pitch):false};
}
